const scenarios = [
  {id:'growth',name:'The growth dilemma',category:'STRATEGY',time:'6 minutes',summary:'A major opportunity arrives while your team is already at capacity.',context:'Your largest client wants an accelerated expansion that could grow annual revenue by 25%. Delivery leaders warn that the current team cannot absorb the work without sacrificing quality. The client needs an answer this week.',stakeholders:'Client sponsor · Delivery team · Finance',rounds:[
    {prompt:'How do you respond to the opportunity?',options:[['Commit to the full expansion','Secure the revenue and ask the team to find a way.',[3,-2,-2],'The client welcomes your commitment. Delivery flags an immediate capacity gap.'],['Negotiate a phased pilot','Validate value and capacity before committing to scale.',[2,2,1],'The client accepts a smaller pilot, provided you define clear milestones.'],['Decline the expansion','Protect existing commitments and service quality.',[-1,1,3],'The team feels protected, but the client starts evaluating other partners.']]},
    {prompt:'Your delivery lead asks how you will resource the next month.',options:[['Reprioritize with the team','Agree what to pause and communicate the impact.',[1,3,2],'Clear priorities give the team room to execute, though a secondary project slips.'],['Bring in external specialists','Trade margin for immediate delivery capacity.',[2,1,0],'Specialists add capacity. Onboarding costs reduce the initial margin.'],['Ask for a short-term stretch','Keep all commitments and reward extra effort.',[2,-3,-2],'Early milestones move quickly, but fatigue and quality concerns rise.']]},
    {prompt:'At the review, results are promising but delivery costs are above plan. What next?',options:[['Scale with explicit guardrails','Set margin, quality, and workload thresholds before expansion.',[2,2,2],'A shared set of thresholds makes the next investment decision clearer.'],['Accelerate to capture momentum','Prioritize market share while demand is strong.',[3,-1,-2],'Growth accelerates while operating risk remains unresolved.'],['Pause and review the economics','Use the evidence to renegotiate scope and pricing.',[0,1,3],'You gain a stronger commercial model, at the cost of some momentum.']]}]},
  {id:'trust',name:'Trust under pressure',category:'PEOPLE & CULTURE',time:'6 minutes',summary:'A high-performing executive is undermining collaboration.',context:'Your commercial director consistently exceeds targets. Two department heads now say their teams are being excluded from decisions and blamed for missed handoffs. A key employee is considering leaving. Your board wants continued growth.',stakeholders:'Commercial director · Department heads · Board',rounds:[
    {prompt:'What is your first move?',options:[['Listen and gather specific examples','Speak privately with the people involved before judging.',[1,3,2],'Specific examples reveal a recurring pattern and give you a basis for a fair conversation.'],['Issue a public warning','Make clear that collaboration is non-negotiable.',[0,-2,1],'The standard is visible, but the director becomes defensive and colleagues hesitate to speak.'],['Wait until the quarter closes','Protect focus on the revenue target.',[2,-3,-2],'Revenue holds, but the employee resigns and distrust deepens.']]},
    {prompt:'The director says their results justify their approach. How do you respond?',options:[['Agree on measurable behavior changes','Pair revenue goals with shared ownership and team feedback.',[2,3,2],'The director has clear expectations and a chance to rebuild trust.'],['Remove them from leadership immediately','Act decisively to protect the team.',[-2,1,2],'The team sees accountability, while the sudden transition disrupts key accounts.'],['Offer confidential coaching only','Give private support without changing performance goals.',[1,0,-1],'The director accepts support, but peers still lack a visible commitment to change.']]},
    {prompt:'The board asks how you will know whether the issue is resolved.',options:[['Review business and team indicators','Track handoffs, retention, feedback, and revenue together.',[2,3,3],'A balanced review reveals whether commercial success is becoming sustainable.'],['Use revenue as the primary signal','Keep accountability centered on commercial outcomes.',[3,-2,-2],'Performance stays legible, while the original collaboration problem may remain hidden.'],['Rely on informal check-ins','Keep the process light and relationship-led.',[0,1,-1],'Conversations improve, but inconsistent evidence makes follow-through harder.']]}]},
  {id:'crisis',name:'The first 24 hours',category:'CRISIS LEADERSHIP',time:'6 minutes',summary:'A service failure puts customer confidence and your reputation at risk.',context:'A critical service outage has affected several enterprise clients. The root cause is still unknown. A customer has posted publicly, your support team is overwhelmed, and the board is asking for a recovery timeline.',stakeholders:'Customers · Incident team · Board',rounds:[
    {prompt:'What do you communicate first?',options:[['Acknowledge what you know','Name the impact, owner, and time of the next update.',[1,3,3],'Customers have a clear source of information without an unsupported recovery promise.'],['Promise recovery within two hours','Provide a confident deadline to calm stakeholders.',[2,-2,-3],'The deadline reassures initially, but engineers cannot yet validate it.'],['Wait for a confirmed root cause','Avoid sharing incomplete information.',[-1,-2,1],'Technical facts become clearer while customers feel left in the dark.']]},
    {prompt:'Several executives are sending requests directly to engineers. What do you do?',options:[['Establish a single incident lead','Create a decision channel and a regular stakeholder briefing.',[2,2,3],'Engineers regain focus and stakeholders know where to get updates.'],['Join every technical discussion','Stay close to each decision yourself.',[0,-1,-1],'Your involvement adds context but slows approvals and fragments attention.'],['Delegate all communication to support','Let technical teams work independently.',[1,-2,0],'Engineers have space, but support lacks authority to answer strategic questions.']]},
    {prompt:'Service is restored. How do you lead the follow-through?',options:[['Publish a learning review and action plan','Assign owners and dates, then verify improvements.',[2,3,3],'Customers see accountable follow-through and the team has a concrete prevention plan.'],['Return immediately to growth priorities','Restore momentum after an expensive disruption.',[3,-1,-3],'Commercial activity resumes, but repeat-failure risks remain.'],['Find and discipline the person responsible','Signal strong individual accountability.',[0,-3,0],'People become more cautious about reporting mistakes, limiting organizational learning.']]}]},
  {id:'ai-adoption',name:'The AI adoption decision',category:'TECHNOLOGY & INNOVATION',time:'6 minutes',summary:'An AI pilot promises faster service, but reliability and workforce concerns remain.',context:'A vendor demonstration suggests AI could reduce customer-service handling time. Your operations team wants a rapid rollout, while staff worry about changing roles. The pilot has not yet been tested on complex customer cases.',stakeholders:'Operations lead · Customer advocates · Technology team · Employees',rounds:[
    {prompt:'How do you authorize the first deployment?',options:[['Launch across all service teams','Capture efficiency gains before the next budget review.',[3,-2,-3],'Simple requests move faster, but complex cases expose gaps that staff must resolve manually.'],['Run a supervised pilot','Limit scope, define review criteria, and retain human escalation.',[1,2,3],'The pilot yields evidence on difficult cases, while wider efficiency gains take longer.'],['Defer adoption for a year','Keep current processes while the technology matures.',[-2,1,2],'Staff retain familiar workflows, but backlogs persist and learning is delayed.']]},
    {prompt:'Employees ask whether efficiency gains will eliminate their roles. What do you do?',options:[['Promise that no roles will ever change','Reduce immediate anxiety with a firm assurance.',[1,1,-2],'Concern eases initially, but the promise limits options you have not yet evaluated.'],['Plan role changes with employees','Explain uncertainties and fund training with clear review points.',[0,3,2],'Employees gain a voice and a transition plan, while training adds cost and time.'],['Leave workforce planning to each manager','Let teams adapt locally as usage grows.',[2,-2,-1],'Some teams adapt quickly, but inconsistent messages increase uncertainty elsewhere.']]},
    {prompt:'The review finds faster responses but recurring errors in complex cases. What next?',options:[['Expand only the validated use cases','Keep complex cases with people and monitor errors.',[2,2,3],'You capture a narrower efficiency gain while preserving an accountable escalation route.'],['Expand and correct errors as they appear','Prioritize learning at scale.',[3,-2,-3],'Usage grows quickly, but customers and staff absorb more correction work.'],['End the deployment','Remove the new system and review alternatives.',[-2,1,2],'The error exposure stops, while useful capabilities and the investment are set aside.']]}]},
  {id:'capital',name:'Competing for investment',category:'RESOURCE ALLOCATION',time:'6 minutes',summary:'A tighter budget forces a choice between growth, reliability, and capability.',context:'Your board has reduced next-year investment funding by 15%. Sales proposes a market launch, operations needs to replace aging systems, and people leaders want management training. Each proposal has credible benefits, but the full portfolio is unaffordable.',stakeholders:'Finance · Sales · Operations · People leaders',rounds:[
    {prompt:'How do you establish investment priorities?',options:[['Fund the strongest revenue forecast','Use near-term growth as the deciding criterion.',[3,-1,-2],'Sales can move quickly, while system dependencies and capability gaps remain underfunded.'],['Agree shared criteria and dependencies','Compare value, risk, capacity, and evidence across proposals.',[1,2,2],'Leaders build a common basis for trade-offs, but the review delays funding decisions.'],['Cut every proposal equally','Share the reduction across all functions.',[0,1,-2],'The allocation appears even, but several proposals fall below a viable delivery size.']]},
    {prompt:'The launch depends on a system upgrade that will consume much of its budget. What do you choose?',options:[['Stage the upgrade and a smaller launch','Fund the dependency and test demand in one segment.',[1,1,3],'The plan is more deliverable, though the initial market reach shrinks.'],['Launch on the existing systems','Accept manual work to preserve the commercial deadline.',[3,-1,-3],'The launch stays on schedule, while workarounds increase strain and failure risk.'],['Fund infrastructure only','Resolve reliability needs before any new market spending.',[-2,0,3],'Operations gains stability, but the market opportunity loses sponsorship.']]},
    {prompt:'At midyear, one investment misses its milestones. How do you respond?',options:[['Release more funding immediately','Give the team resources to recover the original plan.',[1,0,-2],'The team gets breathing room, but you commit more capital before validating the cause.'],['Cancel every unspent allocation','Protect cash until the next planning cycle.',[-2,-1,2],'Cash is preserved, but viable work stalls alongside the troubled investment.'],['Review evidence before the next tranche','Reassess milestones, assumptions, and alternative uses of capital.',[1,2,2],'You can redirect funding with clearer evidence, at the cost of another decision cycle.']]}]},
  {id:'change',name:'When change meets fatigue',category:'TRANSFORMATION',time:'6 minutes',summary:'A strategic transformation is slipping as employees struggle with competing initiatives.',context:'You are six months into a transformation intended to simplify customer delivery. Teams are also handling two other major initiatives. Adoption is uneven, managers report exhaustion, and the board expects visible progress this quarter.',stakeholders:'Transformation sponsor · Frontline managers · Employees · Board',rounds:[
    {prompt:'What do you do about uneven adoption?',options:[['Reaffirm the deadline and require weekly reports','Increase visibility and pressure to deliver.',[2,-2,-2],'Reporting improves, but teams divert time from implementation and hide emerging difficulties.'],['Listen to teams and map competing work','Identify barriers and decide which activities can pause.',[0,3,2],'You surface practical obstacles, while the immediate delivery pace slows.'],['Make adoption optional for now','Give teams discretion until workloads ease.',[-2,1,-1],'Pressure drops, but inconsistent processes make cross-team work harder.']]},
    {prompt:'Managers say they cannot sustain all three initiatives. What do you prioritize?',options:[['Sequence work and stop a lower-value initiative','Reset capacity and explain the trade-off to sponsors.',[1,2,3],'Teams regain focus, while one sponsor loses an expected benefit this quarter.'],['Add temporary implementation support','Buy capacity while keeping the current commitments.',[2,1,0],'Delivery gets help, but onboarding and extra spending reduce the expected savings.'],['Offer recognition for extra effort','Keep the portfolio intact and reward commitment.',[2,-2,-2],'Some milestones recover briefly, while workload and retention concerns grow.']]},
    {prompt:'The board asks for proof that the transformation is working. What do you present?',options:[['Report completed training and launch events','Show the activities delivered against the original plan.',[1,0,-1],'The activity record is clear, but it does not show whether customer delivery improved.'],['Declare success based on one strong team','Use an early success to sustain confidence.',[2,-2,-1],'Confidence rises briefly, while other teams feel their barriers are being overlooked.'],['Show adoption and customer outcomes together','Include gaps, lessons, and the next capacity decision.',[1,3,2],'The board can judge progress against benefits, while unresolved gaps remain visible.']]}]},
  {id:'succession',name:'The succession crossroads',category:'TALENT & SUCCESSION',time:'6 minutes',summary:'A pivotal leader is leaving, and two credible successors offer different strengths.',context:'Your chief operating officer will leave in eight weeks. An internal candidate knows the business but has limited enterprise experience. An external finalist brings transformation expertise but little knowledge of your culture. Key teams need continuity.',stakeholders:'Internal candidate · Board · People team · Operating leaders',rounds:[
    {prompt:'How do you structure the succession decision?',options:[['Appoint the internal candidate immediately','Reward loyalty and minimize uncertainty.',[2,2,-1],'Continuity reassures teams, but enterprise readiness remains untested.'],['Compare both candidates against future needs','Use consistent evidence and a defined decision date.',[0,2,3],'The board gains a defensible comparison, while candidates wait for clarity.'],['Choose the external finalist on reputation','Bring in a leader known for major transformations.',[2,-2,0],'Investors welcome the signal, but fit and operating assumptions still need validation.']]},
    {prompt:'Critical operating knowledge sits with the departing leader. What is your transition priority?',options:[['Document key decisions and assign transition owners','Protect knowledge transfer alongside daily delivery.',[1,2,3],'Teams gain clearer ownership, though handover work temporarily reduces delivery capacity.'],['Ask the departing leader to stay informally available','Preserve continuity without slowing current work.',[2,0,-2],'Immediate work stays on pace, but future access and accountability remain uncertain.'],['Let the successor redesign the operating model','Avoid locking the next leader into old practices.',[1,-1,-2],'The successor gains freedom, while essential context may disappear before they arrive.']]},
    {prompt:'An unsuccessful internal applicant is considering leaving. How do you respond?',options:[['Offer a title without changing responsibilities','Signal recognition quickly.',[1,-1,-1],'The gesture buys time, but limited authority makes the commitment feel thin.'],['Hold a candid development and retention conversation','Share specific feedback and agree meaningful opportunities.',[0,3,2],'The applicant can make an informed choice, while development requires real sponsorship.'],['Focus solely on onboarding the new leader','Treat retention as the applicant’s decision.',[2,-2,-1],'The new leader gets attention, but the organization may lose valuable knowledge.']]}]},
  {id:'integration',name:'One company, two cultures',category:'MERGERS & INTEGRATION',time:'6 minutes',summary:'An acquisition creates pressure for savings while customer relationships need protection.',context:'Your company has acquired a smaller competitor with strong customer loyalty. The board expects savings within six months. The acquired team fears losing its identity, and customers worry that service will become less personal.',stakeholders:'Acquired team · Integration lead · Customers · Board',rounds:[
    {prompt:'What is your first integration move?',options:[['Standardize all processes immediately','Accelerate savings and establish one operating model.',[3,-2,-2],'Duplicate work falls, but unfamiliar processes disrupt service and unsettle the acquired team.'],['Map customer-critical practices together','Agree what must be preserved before sequencing integration.',[0,3,2],'The teams identify valuable practices, while savings arrive later.'],['Keep both businesses fully separate','Protect relationships and avoid early disruption.',[-1,2,-2],'Customers see continuity, but duplicated systems and unclear ownership persist.']]},
    {prompt:'The savings plan would remove overlapping account roles. What do you do?',options:[['Consolidate roles at once','Deliver the announced savings quickly.',[3,-2,-2],'Costs fall, but customers lose familiar contacts before replacements are ready.'],['Retain every overlapping role indefinitely','Prioritize continuity over the savings commitment.',[-2,2,0],'Relationships stay stable, while costs and duplicated accountability remain.'],['Phase handovers around account risk','Set named owners, transition dates, and support for affected staff.',[1,2,2],'Continuity improves, though savings are delayed and transition work consumes capacity.']]},
    {prompt:'Revenue is steady, but acquired-team departures are rising. What next?',options:[['Review retention, service, and savings together','Address departure causes and revisit the integration sequence.',[0,3,2],'You expose risks early, while some integration milestones must move.'],['Keep the savings target as the sole measure','Stay focused on the acquisition business case.',[3,-2,-3],'The cost target remains clear, but lost knowledge threatens future service.'],['Stop the entire integration','Give the acquired team immediate relief.',[-2,1,-1],'Pressure eases, but unresolved structures leave teams uncertain about the long-term model.']]}]},
  {id:'ethics',name:'The pressure to deliver',category:'ETHICS & ACCOUNTABILITY',time:'6 minutes',summary:'An important deal tests your standards as the quarter-end deadline approaches.',context:'A major prospect could close your revenue gap this quarter. The account team says the requested delivery date is unlikely, but a senior sponsor wants the proposal to state it confidently. Finance needs a reliable forecast and delivery staff fear inheriting an impossible promise.',stakeholders:'Account team · Delivery lead · Finance · Executive sponsor',rounds:[
    {prompt:'How do you handle the proposed delivery commitment?',options:[['Use the optimistic date without qualification','Keep the proposal competitive and resolve capacity later.',[3,-2,-3],'The prospect responds positively, while your team inherits an unsupported commitment.'],['Validate scope and offer a credible staged date','Bring delivery evidence into the customer conversation.',[1,2,3],'The proposal becomes more credible, though the prospect may choose a faster competitor.'],['Withdraw from the opportunity','Avoid any chance of an unachievable commitment.',[-3,1,2],'The team avoids the delivery exposure, but a potentially viable deal is lost.']]},
    {prompt:'The executive sponsor asks you to leave delivery concerns out of the forecast review. What do you do?',options:[['Report assumptions and risk explicitly','Give finance a clear view of confidence and dependencies.',[0,3,3],'The forecast is more useful for planning, while the sponsor challenges your approach.'],['Keep the concern in private conversations','Avoid conflict during the review.',[2,-2,-2],'The review is smoother, but decision-makers cannot account for the delivery risk.'],['Confront the sponsor in the wider meeting','Make the disagreement immediately visible.',[-1,-2,1],'The concern is heard, but the confrontation makes constructive resolution harder.']]},
    {prompt:'The review reveals similar optimistic commitments in other proposals. How do you follow through?',options:[['Treat this deal as an isolated exception','Protect selling time and avoid more process.',[2,-2,-3],'Sales activity continues, while the same commitment risks remain elsewhere.'],['Require executive approval for every proposal','Centralize oversight to prevent recurrence.',[-2,0,2],'Oversight increases, but routine deals slow and local accountability weakens.'],['Introduce proportionate commitment checks','Define delivery sign-off thresholds and review exceptions.',[1,2,3],'Teams gain a repeatable standard, at the cost of some additional review work.']]}]}
];
function outcome(choices,scenario){
 const totals=[0,0,0];
 choices.forEach((choice,i)=>{const option=scenario.rounds[i]?.options[choice];if(option)option[2].forEach((n,j)=>totals[j]+=n);});
 return totals.map(n=>Math.max(0,Math.min(100,50+n*5)));
}
if(typeof module!=='undefined')module.exports={scenarios,outcome};
else window.ExecutiveSimulation={scenarios,outcome};
